using System.Diagnostics;using SobhanNotificationHub.Data;using SobhanNotificationHub.Services;
namespace SobhanNotificationHub.Notifications;public sealed class NotificationActionRouter(SobhanApiClient api,LocalCacheDb cache){public async Task RouteAsync(long id,string action,string? reply,CancellationToken ct){if(id<=0)return;try{var url=await api.ActionAsync(id,action,reply,ct);await cache.MarkActionAsync(id,action);LoggingService.Info("action_sent",$"id={id};action={action}");if(action is "open" or "view_ticket" or "view_cartable"&&!string.IsNullOrWhiteSpace(url)&&Uri.TryCreate(url,UriKind.Absolute,out var uri)&&uri.Scheme==Uri.UriSchemeHttps)Process.Start(new ProcessStartInfo(uri.ToString()){UseShellExecute=true});}catch(Exception ex){LoggingService.Error("action_send",ex);}}}
